use std::io::prelude::*;

const BYTES_PER_LINE: usize = 16;
const INPUT: &[u8] = br#"
fn main() {
    println!("Hello, world!");
}"#;

fn main() -> std::io::Result<()> {
    let mut buffer: Vec<u8> = vec![];
    let mut input = INPUT;
    input.read_to_end(&mut buffer)?;

    let mut position_in_input = 0;
    for line in buffer.chunks(BYTES_PER_LINE) {
        print!("[0x{:08x}] ", position_in_input);
        for byte in line {
            print!("{:02x} ", byte);
        }
        println!();
        position_in_input += BYTES_PER_LINE;
    }

    Ok(())
}

use std::io::{self, Cursor, Read, Write};

fn write_numbers<W: Write>(w: &mut W) -> io::Result<()> {
    w.write_all(&1_u32.to_le_bytes())?;
    w.write_all(&2_i8.to_le_bytes())?;
    w.write_all(&3.0_f64.to_le_bytes())?;
    Ok(())
}

fn read_numbers<R: Read>(r: &mut R) -> io::Result<(u32, i8, f64)> {
    let mut b4 = [0u8; 4];
    let mut b1 = [0u8; 1];
    let mut b8 = [0u8; 8];
    r.read_exact(&mut b4)?;
    r.read_exact(&mut b1)?;
    r.read_exact(&mut b8)?;
    Ok((u32::from_le_bytes(b4), i8::from_le_bytes(b1), f64::from_le_bytes(b8)))
}

fn main() -> io::Result<()> {
    let mut w = vec![];
    write_numbers(&mut w)?;
    println!("{:?}", w);

    let mut r = Cursor::new(w);
    println!("{:?}", read_numbers(&mut r)?);
    println!("past the end: {:?}", read_numbers(&mut r).unwrap_err().kind());
    Ok(())
}

use std::io::{self, Cursor, Read, Seek, SeekFrom, Write};

const RECORD: u64 = 8; // id: u32, score: u32

fn main() -> io::Result<()> {
    let mut db = Cursor::new(Vec::new());
    for (id, score) in [(1u32, 50u32), (2, 75), (3, 99)] {
        db.write_all(&id.to_le_bytes())?;
        db.write_all(&score.to_le_bytes())?;
    }

    // read record 2 (the third) directly
    db.seek(SeekFrom::Start(2 * RECORD))?;
    let mut buf = [0u8; 8];
    db.read_exact(&mut buf)?;
    let id = u32::from_le_bytes(buf[0..4].try_into().unwrap());
    let score = u32::from_le_bytes(buf[4..8].try_into().unwrap());
    println!("record 2: id {id}, score {score}");

    // overwrite the score of record 0 in place
    db.seek(SeekFrom::Start(4))?;
    db.write_all(&60u32.to_le_bytes())?;
    println!("file is {} bytes, now at {}", db.get_ref().len(), db.stream_position()?);
    println!("{:?}", &db.get_ref()[..8]);
    Ok(())
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = !0u32;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            let mask = (crc & 1).wrapping_neg(); // all ones if the low bit is set
            crc = (crc >> 1) ^ (0xEDB8_8320 & mask);
        }
    }
    !crc
}

fn main() {
    println!("{:08x}", crc32(b"123456789"));
    let good = b"hello, world";
    let mut bad = *good;
    bad[3] ^= 0b0000_0100; // flip one bit
    println!("{:08x} {:08x}", crc32(good), crc32(&bad));
    println!("{}", String::from_utf8_lossy(&bad));
}

